<div class="section-heading"><div><div class="eyebrow">Financeiro da plataforma</div><h1>Pagamentos</h1><p class="text-secondary mb-0">Acompanhe cobranças confirmadas, pendentes e recusadas.</p></div><a class="btn btn-outline-primary" href="/master/mercadopago">Configurar Mercado Pago</a></div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data</th><th>Empresa</th><th>Plano</th><th>Valor</th><th>Meio de pagamento</th><th>Status</th><th>Referência</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=htmlspecialchars($p['created_at'])?></td><td><?=htmlspecialchars($p['tenant_name'])?></td><td><?=htmlspecialchars($p['plan_name']??'—')?></td><td>R$ <?=number_format((float)$p['amount'],2,',','.')?></td><td><?=htmlspecialchars($p['provider']??'—')?></td><td><span class="badge <?=$p['status']==='paid'?'text-bg-success':($p['status']==='failed'?'text-bg-danger':'text-bg-light')?>"><?=htmlspecialchars(['pending'=>'Pendente','paid'=>'Pago','failed'=>'Não aprovado','refunded'=>'Reembolsado','cancelled'=>'Cancelado','overdue'=>'Vencido'][$p['status']]??$p['status'])?></span></td><td><code><?=htmlspecialchars(substr((string)($p['provider_payment_id']??$p['provider_reference']??''),0,28))?></code></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="7"><div class="empty-state">Nenhum pagamento registrado.</div></td></tr><?php endif;?></tbody></table></div></div>
